'use client';

import { useId, useState, type ReactNode } from 'react';
import './spring-accordion.css';

export interface AccordionItem {
  id: string;
  title: string;
  content: ReactNode;
}

export interface SpringAccordionProps {
  items: AccordionItem[];
  /** Id of the item that starts open. */
  defaultOpen?: string;
  className?: string;
}

/** One section open at a time. Opening overshoots slightly, like a spring. */
export function SpringAccordion({
  items,
  defaultOpen,
  className = '',
}: SpringAccordionProps) {
  const [open, setOpen] = useState<string | null>(defaultOpen ?? null);
  const baseId = useId();
  return (
    <div className={`mg-accordion ${className}`}>
      {items.map((item) => {
        const isOpen = item.id === open;
        return (
          <div key={item.id} className='mg-accordion__item' data-open={isOpen}>
            <h3 className='mg-accordion__heading'>
              <button
                type='button'
                id={`${baseId}-button-${item.id}`}
                className='mg-accordion__button'
                aria-expanded={isOpen}
                aria-controls={`${baseId}-panel-${item.id}`}
                onClick={() => setOpen(isOpen ? null : item.id)}
              >
                {item.title}
                <span className='mg-accordion__mark' aria-hidden='true' />
              </button>
            </h3>
            <div
              id={`${baseId}-panel-${item.id}`}
              role='region'
              aria-labelledby={`${baseId}-button-${item.id}`}
              className='mg-accordion__panel'
            >
              <div className='mg-accordion__clip'>
                <div className='mg-accordion__body'>{item.content}</div>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

.mg-accordion {
  border: 1px solid var(--mg-line, #d6def2);
  border-radius: 12px;
  background: #fff;
  color: var(--mg-ink, #0c1738);
}

.mg-accordion__item + .mg-accordion__item {
  border-top: 1px solid var(--mg-line, #d6def2);
}

.mg-accordion__heading {
  margin: 0;
  font-size: inherit;
}

.mg-accordion__button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  min-height: 48px;
  padding: 0 16px;
  border: 0;
  background: none;
  color: inherit;
  font: inherit;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
}

.mg-accordion__button:focus-visible {
  outline: 2px solid var(--mg-accent, #164cff);
  outline-offset: -2px;
  border-radius: 10px;
}

/* A plus that turns into a minus. */
.mg-accordion__mark {
  position: relative;
  flex: none;
  width: 12px;
  height: 12px;
}

.mg-accordion__mark::before,
.mg-accordion__mark::after {
  position: absolute;
  top: 5px;
  left: 0;
  width: 12px;
  height: 2px;
  border-radius: 2px;
  background: var(--mg-accent, #164cff);
  content: '';
  transition: transform 380ms cubic-bezier(0.3, 1.5, 0.5, 1);
}

.mg-accordion__mark::after {
  transform: rotate(90deg);
}

.mg-accordion__item[data-open='true'] .mg-accordion__mark::after {
  transform: rotate(0deg);
}

.mg-accordion__panel {
  display: grid;
  grid-template-rows: 0fr;
  /* The overshoot in this curve is what gives the spring feel. */
  transition: grid-template-rows 460ms cubic-bezier(0.3, 1.35, 0.5, 1);
}

.mg-accordion__item[data-open='true'] .mg-accordion__panel {
  grid-template-rows: 1fr;
}

.mg-accordion__clip {
  min-height: 0;
  overflow: hidden;
  visibility: hidden;
  transition: visibility 0s 460ms;
}

.mg-accordion__item[data-open='true'] .mg-accordion__clip {
  visibility: visible;
  transition-delay: 0s;
}

.mg-accordion__body {
  padding: 0 16px 16px;
  color: #46527a;
}

@media (prefers-reduced-motion: reduce) {
  .mg-accordion__panel,
  .mg-accordion__clip,
  .mg-accordion__mark::before,
  .mg-accordion__mark::after {
    transition: none;
  }
}
